"""Measuring: the document model becomes line, row and table boxes.

Every paragraph is measured into immutable line boxes first; only then are they
flowed onto pages (see flow.py).  That split is what makes page breaking,
keep-next, widow control, repeated table headers and footnotes tractable.

The rules that make the result line up with Word live here: the 600 dpi device
grid, how a line box is built from font metrics, and where justification takes
its space from.
"""
from __future__ import annotations

import datetime
from dataclasses import replace
from typing import List, Optional

from ..document import (BreakRun, Document, FieldRun, ImageRun, Link, NoteRun,
                        Paragraph, ParaProps, RunProps, ShapeRun,
                        SYMBOL_BULLETS, TabRun, TabStop, Table, TextRun,
                        format_number)
from ..fonts import FontManager, ResolvedFont
from .boxes import (CellBox, LineBox, ParaBox, Piece, RowBox, TableBox, Token)

HIGHLIGHTS = {
    'yellow': 'FFFF00', 'green': '00FF00', 'cyan': '00FFFF', 'magenta': 'FF00FF',
    'blue': '0000FF', 'red': 'FF0000', 'darkBlue': '000080', 'darkCyan': '008080',
    'darkGreen': '008000', 'darkMagenta': '800080', 'darkRed': '800000',
    'darkYellow': '808000', 'darkGray': '808080', 'lightGray': 'C0C0C0',
    'black': '000000', 'white': 'FFFFFF',
}

SYMBOL_FONTS = {'symbol', 'wingdings', 'wingdings 2', 'wingdings 3', 'webdings',
                'monotype sorts', 'zapfdingbats'}

LEADER_CHARS = {'dot': '.', 'middleDot': '·', 'hyphen': '-',
                'underscore': '_', 'heavy': '_'}

MIN_LINE = 0.1
VERT_ALIGN_SCALE = 0.65   # how much smaller Word draws a super/subscript

# Word squeezes a justified line (via negative character spacing) rather than
# pushing a word to the next line, up to roughly a quarter of its white space.
JUSTIFY_SHRINK = 0.25

# Word lays text out on a 600 dpi device grid: font sizes and line heights are
# rounded to 1/600 inch (0.12pt), which is why an 11pt run is drawn at 11.04pt.
DEVICE_GRID = 72.0 / 600.0


def _snap(value: float, grid: float) -> float:
    if not grid:
        return value
    return round(value / grid) * grid


# ---------------------------------------------------------------------------
# text helpers
# ---------------------------------------------------------------------------

def _is_cjk(ch: str) -> bool:
    code = ord(ch)
    return (0x2E80 <= code <= 0x9FFF or 0xAC00 <= code <= 0xD7AF
            or 0xF900 <= code <= 0xFAFF or 0xFF00 <= code <= 0xFF60
            or 0x3000 <= code <= 0x303F)


BREAK_AFTER = '-–—/­'


def _border_padding(borders) -> tuple:
    """Room a paragraph border needs above and below the text."""
    if not borders:
        return 0.0, 0.0

    def room(side):
        border = borders.get(side)
        if border is None or not border.visible:
            return 0.0
        return (border.space or 0.0) + max(0.25, border.size or 0.5)

    return room('top'), room('bottom')


def _space_width(segments) -> float:
    """Total white space currently on the line being built."""
    return sum(t.space_width for _start, _stop, tokens in segments for t in tokens)


def _compress(pieces: List[Piece], shortfall: float) -> List[Piece]:
    """Squeeze a line with negative character spacing, the way Word does."""
    chars = sum(len(p.text) for p in pieces if p.image is None)
    if chars <= 0 or shortfall >= 0:
        return pieces
    delta = shortfall / chars
    out = []
    shift = 0.0
    for piece in pieces:
        moved = replace(piece, x=piece.x + shift)
        if piece.image is None and piece.text:
            count = len(piece.text)
            moved = replace(moved, char_space=piece.char_space + delta,
                            width=piece.width + delta * count)
            shift += delta * count
        out.append(moved)
    return out


def _tokenize_text(text: str):
    """Split text into (word, trailing spaces) units; CJK breaks per glyph."""
    out = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] in ' \t':
            start = i
            while i < n and text[i] in ' \t':
                i += 1
            if out:
                out[-1] = (out[-1][0], out[-1][1] + text[start:i])
            else:
                out.append(('', text[start:i]))
            continue
        start = i
        while i < n and text[i] not in ' \t':
            ch = text[i]
            if _is_cjk(ch):
                if i == start:
                    i += 1
                break
            i += 1
            if ch in BREAK_AFTER and i > start + 1:
                break
        out.append((text[start:i], ''))
    return out


class Layouter:
    def __init__(self, document: Document, fonts: Optional[FontManager] = None,
                 options: Optional[dict] = None):
        self.doc = document
        self.options = options or {}
        self.fonts = fonts or FontManager(
            extra_dirs=self.options.get('font_dirs'),
            use_cache=self.options.get('font_cache', True),
            default_family=self.options.get('default_font', 'Calibri'))
        self.default_tab = document.default_tab if document else 36.0
        grid = self.options.get('device_grid', DEVICE_GRID)
        self.grid = 0.0 if not grid else float(grid)
        self.warnings: list = []
        self._note_counter = 0
        self._notes: dict = {}
        self._page_number = 1
        self._total_pages = 1
        self._page_num_format = 'decimal'
        self._note_mark = ''

    # ------------------------------------------------------------------
    # fonts, colours, pieces
    # ------------------------------------------------------------------
    def font_for(self, props: RunProps, text: str = '') -> ResolvedFont:
        family = props.font_ascii or props.font_hansi
        if text and any(_is_cjk(ch) for ch in text):
            family = props.font_eastasia or family
        if not family:
            family = (props.font_hansi or props.font_eastasia
                      or self.options.get('default_font', 'Calibri'))
        return self.fonts.resolve(family, bool(props.bold), bool(props.italic))

    def _effective_size(self, props: RunProps, snap: bool = True) -> float:
        """The drawn size.

        Word rounds it onto the device grid for drawing but keeps the nominal
        size when measuring text, so ``snap=False`` gives the measuring size.
        """
        size = props.size or 11.0
        if props.vert_align in ('superscript', 'subscript'):
            size *= VERT_ALIGN_SCALE
        return max(1.0, _snap(size, self.grid) if snap else size)

    @staticmethod
    def _line_box_size(props: RunProps, size: float) -> float:
        """The size the line box reserves for a run.

        Word draws superscripts and subscripts smaller but keeps the line as
        tall as the run's own font size, so a line of nothing but superscript
        text is exactly as high as a normal one.
        """
        if props.vert_align in ('superscript', 'subscript'):
            return size / VERT_ALIGN_SCALE
        return size

    def _color(self, props: RunProps) -> str:
        styles = self.doc.styles if self.doc else None
        color = styles.resolve_color(props) if styles else props.color
        return (color or '000000').lstrip('#').upper()

    def _fill(self, shading) -> Optional[str]:
        styles = self.doc.styles if self.doc else None
        if styles is None or shading is None:
            return None
        fill = styles.resolve_fill(shading)
        return fill.upper() if fill else None

    def make_pieces(self, text: str, props: RunProps,
                    link: Optional[Link]) -> List[Piece]:
        if not text:
            return []
        size = self._effective_size(props)
        measure_size = self._effective_size(props, snap=False)
        color = self._color(props)
        rise = props.position or 0.0
        # the shift from super/subscript happens inside the line box, so it is
        # kept apart from w:position, which does make the line taller
        shift = 0.0
        if props.vert_align == 'superscript':
            shift = size * 0.45
        elif props.vert_align == 'subscript':
            shift = -size * 0.15
        highlight = HIGHLIGHTS.get(props.highlight or '')
        shade = self._fill(props.shading)
        char_space = props.char_spacing or 0.0
        scale = float(props.scale or 100)

        pieces: List[Piece] = []
        for chunk, chunk_size in self._case_split(text, props, size):
            family_font = self.font_for(props, chunk)
            chunk = self._map_symbols(chunk, props, family_font)
            measure = chunk_size * (measure_size / size) if size else chunk_size
            for segment, font in self.fonts.segment(chunk, family_font,
                                                    bool(props.bold),
                                                    bool(props.italic)):
                width = self.fonts.width(segment, font, measure, char_space)
                if scale != 100.0:
                    width *= scale / 100.0
                # Word's line box: a snapped natural height, with the font's
                # win-descent below the baseline and everything else above it.
                box_size = self._line_box_size(props, chunk_size)
                height = _snap(font.line_height * box_size, self.grid)
                descent = font.info.win_descent * box_size if font.info \
                    else font.descent * box_size
                descent = min(descent, height * 0.5)
                pieces.append(Piece(
                    text=segment, font=font, size=chunk_size, measure=measure,
                    width=width,
                    color=color, rise=rise + shift, char_space=char_space,
                    scale=scale,
                    underline=(props.underline
                               if props.underline not in (None, 'none') else None),
                    underline_color=(props.underline_color
                                     if props.underline_color not in (None, 'auto')
                                     else None),
                    strike=bool(props.strike), dstrike=bool(props.dstrike),
                    highlight=highlight, shade=shade, link=link,
                    border=props.border,
                    ascent=height - descent + max(0.0, rise),
                    descent=descent + max(0.0, -rise),
                    height=height))
        return pieces

    def _case_split(self, text: str, props: RunProps, size: float):
        if props.caps:
            text = text.upper()
        if not props.small_caps:
            return [(text, size)]
        out = []
        buf = ''
        buf_lower = None
        for ch in text:
            lower = ch.islower()
            if buf and lower != buf_lower:
                out.append((buf.upper() if buf_lower else buf,
                            size * 0.8 if buf_lower else size))
                buf = ''
            buf += ch
            buf_lower = lower
        if buf:
            out.append((buf.upper() if buf_lower else buf,
                        size * 0.8 if buf_lower else size))
        return out

    def _map_symbols(self, text: str, props: RunProps, font: ResolvedFont) -> str:
        """Rewrite Symbol/Wingdings code points when that font is unavailable."""
        family = (props.font_ascii or '').lower()
        has_pua = any(0xF000 <= ord(c) <= 0xF0FF for c in text)
        if family not in SYMBOL_FONTS and not has_pua:
            return text
        if font.info is not None and font.info.family.lower() == family:
            return text
        out = []
        for ch in text:
            mapped = SYMBOL_BULLETS.get(ch)
            if mapped is None and 0xF000 <= ord(ch) <= 0xF0FF:
                code = ord(ch) - 0xF000
                mapped = SYMBOL_BULLETS.get(chr(ord(ch)))
                if mapped is None:
                    mapped = chr(code) if 32 <= code < 127 else '•'
            out.append(mapped or ch)
        return ''.join(out)

    # ------------------------------------------------------------------
    # tokens
    # ------------------------------------------------------------------
    def tokens_for(self, items, avail: float) -> List[Token]:
        """Measure a paragraph's content into break opportunities.

        Word splits runs wherever it likes - formatting, spell-check state,
        revision ids - so a single word routinely arrives as ``Cont`` + ``act``.
        Tokens are therefore joined across run boundaries whenever no white
        space separates them, otherwise lines would break inside words.
        """
        tokens: List[Token] = []
        open_word = False        # the last token ended mid-word

        def add(token, joins: bool):
            if (joins and open_word and tokens and tokens[-1].kind == 'text'
                    and not tokens[-1].space_width and token.kind == 'text'):
                last = tokens[-1]
                last.pieces.extend(token.pieces)
                last.width += token.width
                last.space_pieces = token.space_pieces
                last.space_width = token.space_width
                return
            tokens.append(token)

        for item in items:
            props = item.props
            link = item.link
            if isinstance(item, TextRun):
                parts = _tokenize_text(item.text)
                for index, (word, space) in enumerate(parts):
                    pieces = self.make_pieces(word, props, link) if word else []
                    space_pieces = self.make_pieces(space, props, link) if space else []
                    if not pieces and not space_pieces:
                        continue
                    add(Token(pieces=pieces, space_pieces=space_pieces,
                              width=sum(p.width for p in pieces),
                              space_width=sum(p.width for p in space_pieces)),
                        joins=(index == 0 and bool(word)
                               and not _is_cjk(word[0])))
                open_word = bool(item.text) and not item.text[-1].isspace() \
                    and not _is_cjk(item.text[-1])
                continue
            if isinstance(item, TabRun):
                tokens.append(Token(kind='tab'))
            elif isinstance(item, BreakRun):
                tokens.append(Token(kind='break', break_kind=item.kind))
            elif isinstance(item, ImageRun):
                tokens.append(self._image_token(item, avail))
            elif isinstance(item, FieldRun):
                pieces = self.make_pieces(self._field_text(item), props, link)
                add(Token(pieces=pieces, width=sum(p.width for p in pieces)),
                    joins=True)
                open_word = True
                continue
            elif isinstance(item, NoteRun):
                pieces = self._note_pieces(item)
                # a footnote mark belongs to the word it follows
                add(Token(pieces=pieces, width=sum(p.width for p in pieces)),
                    joins=True)
                open_word = True
                continue
            open_word = False
        return tokens

    def _image_token(self, item: ImageRun, avail: float) -> Token:
        width = item.width or 0.0
        height = item.height or 0.0
        if width <= 0 or height <= 0:
            width, height = self._intrinsic_size(item, width, height)
        if avail > 0 and width > avail:
            scale = avail / width
            width *= scale
            height *= scale
        piece = Piece(text='', width=width, height=height, ascent=height,
                      descent=0.0, image=item, link=item.link, size=max(1.0, height))
        return Token(pieces=[piece], width=width, kind='image')

    @staticmethod
    def _intrinsic_size(item: ImageRun, width, height):
        try:
            from io import BytesIO

            from PIL import Image
            with Image.open(BytesIO(item.data)) as img:
                px_w, px_h = img.size
                dpi = img.info.get('dpi') or (96, 96)
                dpi_x = dpi[0] or 96
                dpi_y = (dpi[1] if len(dpi) > 1 else dpi[0]) or 96
            width = width or px_w * 72.0 / dpi_x
            height = height or px_h * 72.0 / dpi_y
        except Exception:
            width = width or 72.0
            height = height or 72.0
        return width, height

    def _field_text(self, item: FieldRun) -> str:
        kind = item.kind
        if kind == 'PAGE':
            return format_number(self._page_number, self._page_num_format)
        if kind == 'NUMPAGES':
            return format_number(self._total_pages, self._page_num_format)
        if kind == 'SECTIONPAGES':
            return format_number(self._total_pages, self._page_num_format)
        if kind == 'NOTEREF':
            return getattr(self, '_note_mark', '') or ''
        if kind in ('DATE', 'PRINTDATE', 'SAVEDATE', 'CREATEDATE'):
            return item.text or datetime.date.today().strftime('%d/%m/%Y')
        if kind == 'TIME':
            return item.text or datetime.datetime.now().strftime('%H:%M')
        return item.text or ''

    def _note_pieces(self, item: NoteRun) -> List[Piece]:
        store = self.doc.footnotes if item.kind == 'footnote' else self.doc.endnotes
        blocks = store.get(item.note_id)
        self._note_counter += 1
        fmt = self.doc.settings.get(
            'footnote_num_fmt' if item.kind == 'footnote' else 'endnote_num_fmt',
            'decimal')
        mark = format_number(self._note_counter, fmt)
        props = replace(item.props, vert_align='superscript')
        pieces = self.make_pieces(mark, props, item.link)
        key = (item.kind, item.note_id, self._note_counter)
        if blocks and pieces:
            self._notes[key] = (mark, blocks)
            pieces[0].note = key
        return pieces

    # ------------------------------------------------------------------
    # paragraphs
    # ------------------------------------------------------------------
    def layout_paragraph(self, para: Paragraph, width: float,
                         prev: Optional[Paragraph] = None,
                         next_para: Optional[Paragraph] = None) -> ParaBox:
        props = para.props
        left = props.ind_left or 0.0
        right = props.ind_right or 0.0
        hanging = props.ind_hanging or 0.0
        first_indent = -hanging if hanging else (props.ind_first_line or 0.0)
        right_edge = max(left + MIN_LINE, width - right)

        space_before = props.space_before or 0.0
        space_after = props.space_after or 0.0
        if props.contextual_spacing:
            if prev is not None and prev.style_id == para.style_id:
                space_before = 0.0
            if next_para is not None and next_para.style_id == para.style_id:
                space_after = 0.0

        tokens = self.tokens_for(para.items, right_edge - left)
        number_pieces = []
        if para.number is not None and para.number.text:
            number_pieces = self.make_pieces(para.number.text, para.number.props, None)

        lines = self._build_lines(tokens, para, left, right_edge, first_indent,
                                  number_pieces)
        pad_top, pad_bottom = _border_padding(props.borders)
        box = ParaBox(para=para, lines=lines, space_before=space_before,
                      space_after=space_after, pad_top=pad_top,
                      pad_bottom=pad_bottom,
                      left=left, right=right, width=width,
                      shading=self._fill(props.shading), borders=props.borders,
                      keep_next=bool(props.keep_next),
                      keep_lines=bool(props.keep_lines),
                      widow_control=props.widow_control is not False,
                      page_break_before=bool(props.page_break_before),
                      outline_level=self._outline_level(para),
                      title=para.text.strip(), bookmarks=list(para.bookmarks))
        for shape in (i for i in para.items if isinstance(i, ShapeRun)):
            shape_width = min(width, shape.width) if shape.width else width
            box.after_boxes.extend(self.layout_blocks(shape.blocks, shape_width))
        for obj in para.floats:
            boxes = []
            if obj.blocks:
                inner = max(MIN_LINE, (obj.width or width) - 7.2)
                boxes = self.layout_blocks(obj.blocks, inner)
            box.floats.append((obj, boxes))
        return box

    def _outline_level(self, para: Paragraph) -> Optional[int]:
        level = para.props.outline_level
        if level is not None and level < 9:
            return level
        style_id = (para.style_id or '').lower().replace(' ', '')
        if style_id.startswith('heading') and style_id[7:].isdigit():
            return int(style_id[7:]) - 1
        return None

    def _next_tab(self, x: float, stops, right_edge: float,
                  extra: Optional[float] = None) -> Optional[TabStop]:
        candidates = [s for s in stops if s.align != 'clear']
        if extra is not None:
            candidates = candidates + [TabStop(pos=extra, align='left')]
            candidates.sort(key=lambda s: s.pos)
        for stop in candidates:
            if stop.pos > x + 0.01:
                return stop
        default = self.default_tab or 36.0
        pos = (int(x / default) + 1) * default
        while pos <= x + 0.01:
            pos += default
        if pos >= right_edge:
            return None
        return TabStop(pos=pos, align='left', leader='none')

    def _build_lines(self, tokens: List[Token], para: Paragraph, left: float,
                     right_edge: float, first_indent: float,
                     number_pieces: List[Piece]) -> List[LineBox]:
        lines: List[LineBox] = []
        stops = list(para.props.tabs or ())
        align = para.props.align or 'left'
        justified = align in ('both', 'justify', 'distribute')
        hanging_stop = left if (para.props.ind_hanging or number_pieces) else None
        index = 0
        first = True
        while True:
            # A negative indent is legitimate: Word lets text reach back into
            # the margin or the cell padding, and forms rely on it.
            start_x = left + (first_indent if first else 0.0)
            segments = [[start_x, None, []]]
            pen = start_x
            label = None
            if first and number_pieces:
                label = number_pieces
                label_end = start_x + sum(p.width for p in number_pieces)
                suffix = para.number.suffix if para.number else 'tab'
                if suffix == 'tab':
                    stop = self._next_tab(label_end, stops, right_edge, hanging_stop)
                    pen = max(label_end, stop.pos if stop else label_end)
                elif suffix == 'space':
                    pen = label_end + self.fonts.width(' ', number_pieces[0].font,
                                                       number_pieces[0].measure)
                else:
                    pen = label_end
                segments[0][0] = pen
            forced_break = None
            placed_any = False
            while index < len(tokens):
                token = tokens[index]
                if token.kind == 'break':
                    index += 1
                    forced_break = token.break_kind
                    placed_any = True
                    break
                if token.kind == 'tab':
                    stop = self._next_tab(pen, stops, right_edge, hanging_stop)
                    index += 1
                    placed_any = True
                    if stop is None:
                        forced_break = 'line'
                        break
                    if stop.align in ('left', 'bar'):
                        pen = max(pen, stop.pos)
                        segments.append([pen, stop, []])
                    else:
                        segments.append([None, stop, []])
                    continue
                if pen + token.width > right_edge + 0.01 and placed_any:
                    if not justified:
                        break
                    # the line's own trailing space may hang past the margin,
                    # so it counts towards what can be squeezed out
                    budget = JUSTIFY_SHRINK * (_space_width(segments)
                                               + token.space_width)
                    if pen + token.width - budget > right_edge + 0.01:
                        break
                if pen + token.width > right_edge + 0.01 and not placed_any:
                    split = self._split_long_token(token, right_edge - pen)
                    if split is not None:
                        head, tail = split
                        segments[-1][2].append(head)
                        tokens[index] = tail
                        pen += head.width
                        placed_any = True
                        break
                segments[-1][2].append(token)
                pen += token.total
                index += 1
                placed_any = True
            line = self._compose_line(segments, label, left, right_edge, align,
                                      last_line=index >= len(tokens),
                                      forced_break=forced_break, para=para)
            lines.append(line)
            if forced_break == 'page':
                line.page_break = True
            first = False
            number_pieces = []
            if index >= len(tokens):
                break
            if not placed_any:
                break
        if not lines:
            lines.append(self._compose_line([[left + first_indent, None, []]],
                                            number_pieces, left, right_edge, align,
                                            True, None, para))
        lines[-1].ends_paragraph = True
        empty_height, empty_ascent = self._empty_line_height(para)
        for line in lines:
            if line.height <= 0:
                line.height = empty_height
                line.natural = empty_height
                # a multiple scales an empty paragraph's line as well, so the
                # mark's own height is what it scales
                line.text_natural = empty_height
                line.ascent = empty_ascent
                line.descent = empty_height - empty_ascent
        return lines

    def _split_long_token(self, token: Token, avail: float):
        if avail <= 0 or not token.pieces:
            return None
        head_pieces: List[Piece] = []
        tail_pieces: List[Piece] = []
        remaining = avail
        done = False
        for piece in token.pieces:
            if done:
                tail_pieces.append(piece)
                continue
            if piece.image is not None or piece.width <= remaining:
                head_pieces.append(piece)
                remaining -= piece.width
                continue
            text = piece.text
            lo, hi = 0, len(text)
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if self.fonts.width(text[:mid], piece.font, piece.measure,
                                    piece.char_space) <= remaining:
                    lo = mid
                else:
                    hi = mid - 1
            cut = max(1, lo)
            if cut >= len(text):
                head_pieces.append(piece)
                done = True
                continue
            head_pieces.append(replace(
                piece, text=text[:cut],
                width=self.fonts.width(text[:cut], piece.font, piece.measure,
                                       piece.char_space)))
            tail_pieces.append(replace(
                piece, text=text[cut:],
                width=self.fonts.width(text[cut:], piece.font, piece.measure,
                                       piece.char_space)))
            done = True
        if not head_pieces or not tail_pieces:
            return None
        head = Token(pieces=head_pieces, width=sum(p.width for p in head_pieces))
        tail = Token(pieces=tail_pieces, width=sum(p.width for p in tail_pieces),
                     space_pieces=token.space_pieces,
                     space_width=token.space_width)
        return head, tail

    def _compose_line(self, segments, label_pieces, left, right_edge, align,
                      last_line, forced_break, para) -> LineBox:
        placed: List[Piece] = []
        pen = segments[0][0] or left
        for start_x, stop, tokens in segments:
            content_width = sum(t.width for t in tokens)
            if tokens:
                content_width += sum(t.space_width for t in tokens[:-1])
            if start_x is None and stop is not None:
                if stop.align == 'right':
                    start_x = stop.pos - content_width
                elif stop.align == 'center':
                    start_x = stop.pos - content_width / 2.0
                elif stop.align == 'decimal':
                    start_x = stop.pos - self._decimal_offset(tokens)
                else:
                    start_x = stop.pos
                start_x = max(pen, start_x)
            if start_x is None:
                start_x = pen
            if stop is not None and stop.leader not in (None, 'none') and start_x > pen:
                placed.extend(self._leader_pieces(pen, start_x, stop.leader, tokens,
                                                  para))
            x = start_x
            for token in tokens:
                for piece in token.pieces:
                    placed.append(replace(piece, x=x))
                    x += piece.width
                for piece in token.space_pieces:
                    placed.append(replace(piece, x=x))
                    x += piece.width
            pen = max(pen, x)

        end_x = pen
        while placed and placed[-1].image is None and not placed[-1].text.strip():
            end_x = placed[-1].x
            placed.pop()

        if align in ('center', 'right', 'end') and len(segments) == 1:
            extra = right_edge - end_x
            if extra > 0:
                shift = extra / 2.0 if align == 'center' else extra
                placed = [replace(p, x=p.x + shift) for p in placed]
                end_x += shift
        elif align in ('both', 'justify', 'distribute') and not last_line \
                and forced_break is None and len(segments) == 1 and placed:
            if end_x > right_edge + 0.01:
                placed = _compress(placed, right_edge - end_x)
            else:
                placed = self._justify(placed, right_edge)
            end_x = right_edge

        if label_pieces:
            if para.props.ind_hanging:
                label_x = left - para.props.ind_hanging
            elif para.props.ind_first_line:
                label_x = left + para.props.ind_first_line
            else:
                label_x = left
            if para.number is not None and para.number.align in ('right', 'end'):
                label_x = ((segments[0][0] if segments[0][0] is not None else left)
                           - sum(p.width for p in label_pieces))
            for piece in label_pieces:
                placed.insert(0, replace(piece, x=label_x))
                label_x += piece.width

        line = LineBox(pieces=placed, width=max(0.0, end_x - left))
        if placed:
            line.ascent = max(p.ascent for p in placed)
            line.descent = max(p.descent for p in placed)
            line.natural = max(max(p.height for p in placed),
                               line.ascent + line.descent)
            text = [p for p in placed if p.image is None]
            line.text_natural = max((p.height for p in text), default=0.0)
            line.height = line.natural
            line.notes = [p.note for p in placed if p.note]
        return line

    def _decimal_offset(self, tokens) -> float:
        offset = 0.0
        for token in tokens:
            for piece in token.pieces:
                idx = piece.text.find('.')
                if idx >= 0:
                    return offset + self.fonts.width(piece.text[:idx], piece.font,
                                                     piece.measure,
                                                     piece.char_space)
                offset += piece.width
            offset += token.space_width
        return offset

    def _leader_pieces(self, start, end, leader, tokens, para) -> List[Piece]:
        char = LEADER_CHARS.get(leader)
        if not char or end - start < 1:
            return []
        sample = None
        for token in tokens:
            if token.pieces:
                sample = token.pieces[0]
                break
        if sample is None:
            size = self._effective_size(para.mark_props)
            sample = Piece(font=self.font_for(para.mark_props), size=size,
                           measure=self._effective_size(para.mark_props,
                                                        snap=False))
        unit = self.fonts.width(char, sample.font, sample.measure or sample.size)
        if unit <= 0:
            return []
        count = int((end - start) / unit)
        if count <= 0:
            return []
        width = unit * count
        return [replace(sample, text=char * count, width=width, x=end - width,
                        underline=None, strike=False, dstrike=False,
                        highlight=None, shade=None, link=None, image=None,
                        note=None, leader=True)]

    def _justify(self, pieces: List[Piece], right_edge: float) -> List[Piece]:
        gaps = [i for i, p in enumerate(pieces)
                if p.image is None and p.text and not p.text.strip()]
        if not gaps:
            return pieces
        end = pieces[-1].x + pieces[-1].width
        extra = right_edge - end
        if extra <= 0.01:
            return pieces
        per_gap = extra / len(gaps)
        out = []
        shift = 0.0
        for i, piece in enumerate(pieces):
            out.append(replace(piece, x=piece.x + shift))
            if i in gaps:
                shift += per_gap
        return out

    def _empty_line_height(self, para: Paragraph) -> float:
        props = para.mark_props
        size = self._line_box_size(props, self._effective_size(props))
        font = self.font_for(props)
        height = max(MIN_LINE, _snap(font.line_height * size, self.grid))
        descent = (font.info.win_descent * size if font.info
                   else font.descent * size)
        return height, max(0.0, height - min(descent, height * 0.5))

    def apply_line_spacing(self, box: ParaBox):
        props = box.para.props if box.para else ParaProps()
        rule = props.line_rule or 'auto'
        value = props.line
        for line in box.lines:
            natural = line.natural or line.height
            if value is None:
                line.height = natural
                continue
            if rule == 'exact':
                # an exact height clips the line; the baseline keeps its descent
                line.height = max(MIN_LINE, value)
                line.ascent = max(0.0, line.height - line.descent)
            elif rule == 'atLeast':
                line.height = max(natural, value)
            else:
                # Word keeps the baseline where it is and adds the extra
                # leading of a multiple below the line.  A multiple scales the
                # text's own height; a taller inline image just sets a floor.
                scaled = _snap(line.text_natural * (value or 1.0), self.grid) \
                    if line.text_natural else 0.0
                line.height = max(MIN_LINE, scaled, natural)

    # ------------------------------------------------------------------
    # tables
    # ------------------------------------------------------------------
    def layout_table(self, table: Table, width: float) -> TableBox:
        widths = self._column_widths(table, width)
        box = TableBox(widths=widths, width=sum(widths))
        align = table.props.align
        indent = table.props.indent or 0.0
        default_margins = {'left': 5.4, 'right': 5.4, 'top': 0.0, 'bottom': 0.0}
        default_margins.update(table.props.cell_margins or {})
        if align == 'center':
            box.x = max(0.0, (width - box.width) / 2.0)
        elif align in ('right', 'end'):
            box.x = max(0.0, width - box.width)
        elif table.nesting or self.doc.settings.get('compat_mode', 12) >= 15:
            box.x = indent
        else:
            # Before Word 2013, w:tblInd was measured to the text inside the
            # first cell, so the table's own edge sits a cell margin further
            # left.  From compatibility mode 15 on it means the edge itself.
            box.x = indent - default_margins.get('left', 5.4)

        for row_index, row in enumerate(table.rows):
            row_box = RowBox(header=row.header, cant_split=bool(row.props.cant_split))
            column = 0
            for cell in row.cells:
                span = max(1, cell.grid_span)
                cell_width = sum(widths[column:column + span])
                if cell_width <= 0:
                    cell_width = widths[min(column, len(widths) - 1)] if widths else width
                margins = dict(default_margins)
                margins.update(cell.props.margins or {})
                inner = max(MIN_LINE, cell_width - margins.get('left', 5.4)
                            - margins.get('right', 5.4))
                cell_box = CellBox(width=cell_width, x=sum(widths[:column]),
                                   props=cell.props, grid_span=span,
                                   v_merge=cell.v_merge, margins=margins,
                                   borders=cell.props.borders,
                                   shading=self._fill(cell.props.shading),
                                   v_align=cell.props.v_align or 'top')
                if cell.v_merge != 'continue':
                    cell_box.boxes = self.layout_blocks(cell.blocks, inner)
                row_box.cells.append(cell_box)
                column += span
            def cell_height(cell):
                return (cell.content_height + cell.margins.get('top', 0.0)
                        + cell.margins.get('bottom', 0.0))

            # A vertically merged cell's content is shared by every row it
            # spans, so it must not inflate the first one; the merge pass below
            # grows the last row if the content really does not fit.
            heights = [cell_height(c) for c in row_box.cells if c.v_merge is None]
            if not heights:
                heights = [cell_height(c) for c in row_box.cells
                           if c.v_merge != 'continue']
            height = max(heights) if heights else 0.0
            # The row also has to hold its horizontal borders; neighbouring
            # rows share one, so only the first row pays for its top edge.
            row_box.border_top = (self._border_room(row_box.cells, 'top')
                                  if row_index == 0 else 0.0)
            row_box.border_bottom = self._border_room(row_box.cells, 'bottom')
            height += row_box.border_top + row_box.border_bottom
            if row.props.height:
                if row.props.height_rule == 'exact':
                    height = row.props.height
                else:
                    height = max(height, row.props.height)
            row_box.height = max(height, 2.0)
            box.rows.append(row_box)
        self._resolve_vertical_merges(box)
        box.repeat_header = [r for r in box.rows if r.header]
        if box.repeat_header and box.repeat_header != box.rows[:len(box.repeat_header)]:
            box.repeat_header = []
        return box

    def _border_room(self, cells, side: str) -> float:
        room = 0.0
        for cell in cells:
            border = (cell.borders or {}).get(side)
            if border is not None and border.visible:
                room = max(room, border.size or 0.5)
        return _snap(room, self.grid) if room else 0.0

    def _resolve_vertical_merges(self, box: TableBox):
        for row_index, row in enumerate(box.rows):
            for cell in row.cells:
                if cell.v_merge != 'restart':
                    continue
                span = 1
                for below in box.rows[row_index + 1:]:
                    match = next((c for c in below.cells
                                  if abs(c.x - cell.x) < 0.5
                                  and c.v_merge == 'continue'), None)
                    if match is None:
                        break
                    span += 1
                cell.span_rows = span
                if span > 1:
                    needed = (cell.content_height + cell.margins.get('top', 0.0)
                              + cell.margins.get('bottom', 0.0))
                    available = sum(r.height for r in box.rows[row_index:row_index + span])
                    if needed > available:
                        box.rows[row_index + span - 1].height += needed - available

    def _column_widths(self, table: Table, avail: float) -> List[float]:
        grid = [w for w in table.grid if w]
        columns = len(grid)
        if not columns:
            columns = max((sum(max(1, c.grid_span) for c in row.cells)
                           for row in table.rows), default=1)
            grid = [avail / columns] * columns
        declared = [0.0] * columns
        for row in table.rows:
            column = 0
            for cell in row.cells:
                span = max(1, cell.grid_span)
                if cell.width and span == 1 and column < columns:
                    declared[column] = max(declared[column], cell.width)
                column += span
        widths = [declared[i] or grid[i] for i in range(columns)]
        total = sum(widths)
        if total <= 0:
            return [avail / columns] * columns
        explicit = table.props.width_type == 'dxa' and table.props.width
        target = None
        if table.props.width_type == 'pct' and table.props.width:
            target = avail * (table.props.width / 100.0)
        elif explicit:
            target = table.props.width
        if target and abs(total - target) > 0.5:
            scale = target / total
            widths = [w * scale for w in widths]
            total = sum(widths)
        if total > avail + 0.5 and not explicit:
            # An explicitly sized table keeps its width and runs past the
            # margin, exactly as Word draws it; only a table that asked to fit
            # the text column gets squeezed into it.
            scale = avail / total
            widths = [w * scale for w in widths]
        return widths

    # ------------------------------------------------------------------
    # block dispatch
    # ------------------------------------------------------------------
    def layout_blocks(self, blocks, width: float) -> List[object]:
        out: List[object] = []
        for index, block in enumerate(blocks):
            if isinstance(block, Paragraph):
                prev = blocks[index - 1] if index else None
                nxt = blocks[index + 1] if index + 1 < len(blocks) else None
                box = self.layout_paragraph(
                    block, width,
                    prev if isinstance(prev, Paragraph) else None,
                    nxt if isinstance(nxt, Paragraph) else None)
                self.apply_line_spacing(box)
                out.append(box)
                if box.after_boxes:
                    out.extend(box.after_boxes)
                    box.after_boxes = []
            elif isinstance(block, Table):
                out.append(self.layout_table(block, width))
        return self._collapse_spacing(out)

    def _collapse_spacing(self, boxes: List[object]) -> List[object]:
        """Word keeps max(space after, space before), it does not add them."""
        if self.options.get('paragraph_spacing') == 'add':
            return boxes
        previous = None
        for box in boxes:
            if isinstance(box, ParaBox):
                if previous is not None:
                    carried = previous.space_after
                    previous.space_after = 0.0
                    box.space_before = max(box.space_before, carried)
                previous = box
            else:
                previous = None
        return boxes
